import fs from 'fs';
import chalk from 'chalk';
import { resolveToken, retryOnAuthError } from '../core/credentials.js';
import { syncCapabilities } from '../core/capabilities.js';
import { scanFiles, warnStrayFiles } from '../core/scanner.js';
import { syncedDirs, ROOT_FILES, MODULE_ROOT, findDisallowedModules } from '../core/project-layout.js';
import { localDiff } from '../core/local-diff.js';
import { batchDeploy, getFiles, prepareStatic, uploadBlob } from '../api/endpoints.js';
import { describeServerError } from '../api/client.js';
import { pathToModule, replaceSnapshot } from '../core/snapshot.js';
import { readWd, existsWd, displayPath, toModulePath } from '../core/workdir.js';
import { loadState, saveState } from '../core/state.js';
import { loadProjectConfig, configFileName } from '../core/project-config.js';
import { scanStatic, staticDiff, loadStaticSnapshot, saveStaticSnapshot, formatBytes } from '../core/static.js';
import { formatBriefSummary } from '../core/db-changes.js';
import { confirm, closePrompts } from '../utils/prompt.js';
import {
  done,
  modified,
  newFile,
  deleted,
  info,
  warn,
  fatal,
} from '../utils/logger.js';
import { createSpinner } from '../utils/spinner.js';

const SCHEMA_FILE = 'schema.js';

export function registerDeploy(program) {
  program
    .command('push [files...]')
    .description(
      "Deploy changed modules and the Mini App's build to the cloud in one batch. " +
      'Optional files/dirs narrow what is sent.'
    )
    .option('--force', 'Skip concurrency check — overwrite whatever is in the cloud')
    .action(async (targetFiles, options) => {
      // Refresh the project layout before scanning.
      await syncCapabilities();

      const scanned = scanFiles();
      const projectConfig = loadProjectConfig();

      // Targets are files or directories. The static source folder as a target
      // selects the static section only.
      let targeted = false;
      let targetSet = null;
      let staticTargeted = false;
      if (targetFiles && targetFiles.length) {
        const source = projectConfig.static?.source;
        const isStaticTarget = (t) => source && toModulePath(t).replace(/\/+$/, '') === source;
        staticTargeted = targetFiles.some(isStaticTarget);
        const codeTargets = targetFiles.filter((t) => !isStaticTarget(t));
        if (codeTargets.length) {
          targeted = true;
          targetSet = resolveTargets(codeTargets, scanned);
        }
      } else {
        warnStrayFiles();
      }
      // A targeted code push leaves static alone, and vice versa.
      const wantCode = !staticTargeted || targeted;
      const wantStatic = !targeted || staticTargeted;

      // Reject module names the directory doesn't allow before the round-trip.
      const disallowed = findDisallowedModules(scanned);
      if (disallowed.length) {
        const d = disallowed[0];
        fatal(
          `${d.file}: "${d.name}" is not a valid module name in ${d.dir}/. ` +
          `Allowed: ${d.allowed.join(', ')}.`
        );
      }

      const diff = localDiff();
      const staticPlan = wantStatic ? planStatic(projectConfig.static) : null;

      console.log('\nChecking changes...');
      const changedPaths = [];
      const deletedPaths = [];

      if (wantCode) {
        for (const f of diff.modified) {
          if (targeted && !targetSet.has(f.path)) continue;
          modified(displayPath(f.path));
          changedPaths.push(f.path);
        }
        for (const f of diff.newLocal) {
          if (targeted && !targetSet.has(f.path)) continue;
          newFile(displayPath(f.path));
          changedPaths.push(f.path);
        }
        for (const f of diff.remoteOnly) {
          if (targeted && !targetSet.has(f.path)) continue;
          deleted(displayPath(f.path));
          deletedPaths.push(f.path);
        }
      }
      if (staticPlan?.changed) printStaticPlan(staticPlan);

      const codeChanged = changedPaths.length + deletedPaths.length > 0;
      const staticChanged = Boolean(staticPlan?.changed);
      if (!codeChanged && !staticChanged) {
        info('\nNo changes to deploy.');
        return;
      }

      // The manifest is the full module set: anything absent from it is deleted
      // on the server. It is sent only when code changed.
      // Only root files and `synced` directories are deployed.
      const synced = new Set(syncedDirs());
      const inDeployedSpace = (p) => {
        if (ROOT_FILES.includes(p)) return true;
        return synced.has(p.split(/[\\/]/)[0]);
      };

      // A targeted push sends no source for untargeted new modules, so they
      // stay out of the manifest.
      const newLocalSet = new Set(diff.newLocal.map((f) => f.path));
      const manifestPaths = scanned.filter((p) => {
        if (!inDeployedSpace(p)) return false;
        if (targeted && newLocalSet.has(p) && !targetSet.has(p)) return false;
        return true;
      });
      // A targeted push never prunes: remote-only modules stay in the manifest.
      if (targeted) {
        for (const f of diff.remoteOnly) {
          if (inDeployedSpace(f.path)) manifestPaths.push(f.path);
        }
      }

      const manifest = codeChanged ? manifestPaths.map(pathToModule) : undefined;

      const changed_sources = {};
      for (const p of changedPaths) {
        if (!inDeployedSpace(p)) continue;
        changed_sources[pathToModule(p)] = readWd(p);
      }

      const state = loadState();
      let expected_revision = options.force ? null : state.last_known_revision;

      // A null expected_revision is an unconditional deploy. A never-synced
      // project must not overwrite a bot that already has content without --force.
      if (expected_revision == null && !options.force) {
        let remote;
        try {
          remote = await retryOnAuthError(async () => getFiles(await resolveToken()));
        } catch (err) {
          fatal(describeServerError(err));
        }
        const remoteCount = Object.keys(remote?.canonical_modules || {}).length;
        if (remoteCount > 0 || remote?.static) {
          const what = remoteCount > 0
            ? `${remoteCount} deployed module${remoteCount === 1 ? '' : 's'}`
            : 'a deployed static site';
          fatal(
            `This bot already has ${what}` +
            (remote.revision != null ? ` (revision ${remote.revision})` : '') +
            `, but this project has never synced with it.\n` +
            `  Run "tgcloud fetch" to review the difference, then push,\n` +
            `  or "tgcloud push --force" to overwrite the bot with your local project.`
          );
        }
        // Empty bot: adopt its revision so the deploy stays conditional.
        if (remote?.revision != null) expected_revision = remote.revision;
      }

      if (deletedPaths.length) {
        const n = deletedPaths.length;
        const plural = n === 1 ? '' : 's';
        const isTTY = process.stdout.isTTY || process.env.TGCLOUD_ASSUME_TTY === '1';
        // A full push deletes remote modules that are absent locally; confirm
        // first in an interactive terminal.
        if (!targeted && !options.force && isTTY) {
          const ok = await confirm(
            `\n${n} module${plural} in the cloud ${n === 1 ? 'is' : 'are'} absent locally and will be DELETED. Continue?`
          );
          closePrompts();
          if (!ok) { info('Cancelled.'); return; }
        } else {
          info(`\n${n} module${plural} will be deleted in the cloud (absent locally).`);
        }
      }

      // Static blobs are uploaded before the deploy request, so a failed upload
      // leaves the bot unchanged.
      const startTime = Date.now();
      let staticSection;
      let uploaded = null;
      if (staticChanged) {
        if (staticPlan.remove) {
          staticSection = { hash: false };
        } else {
          try {
            const r = await retryOnAuthError(() => uploadStatic(staticPlan));
            staticSection = { hash: r.hash };
            uploaded = r;
          } catch (err) {
            console.error(chalk.red('Error: ') + describeStaticError(err, staticPlan));
            process.exit(1);
          }
        }
      }

      const changeCount = changedPaths.length + deletedPaths.length + (staticChanged ? 1 : 0);
      const deployingLine = `Deploying ${changeCount} change${changeCount === 1 ? '' : 's'}...`;
      console.log('');

      let response;
      try {
        response = await retryOnAuthError(async () => {
          const token = await resolveToken();
          const spinner = createSpinner(deployingLine);
          spinner.start();
          try {
            const r = await batchDeploy(token, { expected_revision, manifest, changed_sources, static: staticSection });
            spinner.stop();
            return r;
          } catch (err) {
            spinner.stop();
            throw err;
          }
        });
      } catch (err) {
        if (isRevisionMismatch(err)) {
          showRevisionMismatchHelp(err);
        } else {
          console.error(chalk.red('Error: ') + describeStaticError(err, staticPlan));
        }
        process.exit(1);
      }

      console.log(deployingLine); // header above the results; the spinner line is erased on stop
      for (const p of changedPaths) done(displayPath(p));
      for (const p of deletedPaths) done(displayPath(p), 'deleted');
      if (staticChanged) {
        if (staticPlan.remove) done(`static`, 'removed');
        else if (uploaded.count === 0) {
          // Config-only change, or every changed blob is already stored.
          const files = staticPlan.diff.added.length + staticPlan.diff.modified.length + staticPlan.diff.deleted.length;
          done(`${staticPlan.source}/`, files ? `${files} file${files === 1 ? '' : 's'} changed (already stored on the server)` : 'config updated');
        } else done(`${staticPlan.source}/`, `${uploaded.count} file${uploaded.count === 1 ? '' : 's'} uploaded (${formatBytes(uploaded.bytes)})`);
      }

      // The response describes the full state. A response without `static`
      // leaves the static snapshot as it is.
      if (response?.canonical_modules) {
        replaceSnapshot(response.canonical_modules);
      }
      if (response && 'static' in response) {
        saveStaticSnapshot(response.static);
      }
      if (response?.revision != null) {
        const s = loadState();
        s.last_known_revision = response.revision;
        saveState(s);
      }

      const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
      info(`\nDone in ${elapsed}s`);
      if (staticChanged && !staticPlan.remove && response?.static?.url) {
        info(`Static: ${response.static.url}`);
      }

      // push never applies DB migrations; it only reports pending changes.
      const schemaDeployed = changedPaths.includes(SCHEMA_FILE);
      if (schemaDeployed && response?.db_changes?.length) {
        const n = response.db_changes.length;
        console.log('');
        console.log(chalk.bold(`Schema out of sync — ${n} change${n === 1 ? '' : 's'}:`));
        console.log(formatBriefSummary(response.db_changes));
        console.log('');
        info('Run "tgcloud migrate" to apply schema changes to the database.');
      }
    });
}

/**
 * Plan the static section of this push:
 *   null                                    — no `static` block
 *   { remove: true, changed }               — `"static": false`
 *   { source, config, scan, diff, changed } — a build to upload
 * A missing or empty build folder is fatal.
 */
function planStatic(block) {
  if (!block) return null;
  const snapshot = loadStaticSnapshot();
  if (block.remove) return { remove: true, changed: Boolean(snapshot) };
  const scan = scanStatic(block.source);
  if (!scan) {
    fatal(`Static source folder "${block.source}/" not found (${configFileName()} → static). Build the app first.`);
  }
  if (!Object.keys(scan.manifest).length) {
    fatal(`Static source folder "${block.source}/" is empty. Build the app first.`);
  }
  const d = staticDiff(scan, block.config, snapshot);
  return { source: block.source, config: block.config, scan, diff: d, changed: d.changed };
}

function printStaticPlan(plan) {
  if (plan.remove) {
    deleted(`static (${configFileName()}: "static": false)`);
    return;
  }
  const { diff, scan, source } = plan;
  for (const p of diff.added) newFile(`${source}/${p}`);
  for (const p of diff.modified) modified(`${source}/${p}`);
  for (const p of diff.deleted) deleted(`${source}/${p}`);
  // On a first deploy the config line is omitted.
  if (diff.configChanged && diff.unchanged + diff.modified.length + diff.deleted.length > 0) modified(`static config (${configFileName()})`);
  if (scan.nonNfc.length) {
    warn(
      `${scan.nonNfc.length} static path${scan.nonNfc.length === 1 ? ' is' : 's are'} not NFC-normalized ` +
      `(e.g. ${scan.nonNfc[0]}); the server matches URLs byte-exact — prefer ASCII file names.`
    );
  }
}

const UPLOAD_CONCURRENCY = 4;

/**
 * Prepare the bundle, upload the missing blobs, return { hash, count, bytes }.
 * The bundle hash is computed by the server.
 */
async function uploadStatic(plan) {
  const token = await resolveToken();
  const { manifest, abs } = plan.scan;
  const byHash = new Map();
  for (const [p, e] of Object.entries(manifest)) byHash.set(e.hash, p);

  const spinner = createSpinner('Preparing static version...');
  spinner.start();
  let prepared;
  try {
    prepared = await prepareStatic(token, manifest, plan.config);
  } finally {
    spinner.stop();
  }
  const missing = Array.isArray(prepared.missing) ? prepared.missing : [];
  const total = missing.reduce((n, h) => n + (manifest[byHash.get(h)]?.size ?? 0), 0);
  if (!missing.length) return { hash: prepared.hash, count: 0, bytes: 0 };

  let sent = 0;
  const progress = createSpinner(`Uploading ${missing.length} file${missing.length === 1 ? '' : 's'} (${formatBytes(total)})...`);
  progress.start();
  const queue = [...missing];
  const worker = async () => {
    while (queue.length) {
      const hash = queue.shift();
      const rel = byHash.get(hash);
      if (rel === undefined) continue; // not in the manifest
      const bytes = fs.readFileSync(abs[rel]);
      await uploadWithRetry(token, hash, prepared.hash, bytes);
      sent++;
      progress.text = `Uploading ${sent}/${missing.length} (${formatBytes(total)})...`;
    }
  };
  try {
    await Promise.all(Array.from({ length: Math.min(UPLOAD_CONCURRENCY, missing.length) }, worker));
  } finally {
    progress.stop();
  }
  return { hash: prepared.hash, count: missing.length, bytes: total };
}

async function uploadWithRetry(token, hash, bundle, bytes) {
  for (let attempt = 0; ; attempt++) {
    try {
      return await uploadBlob(token, hash, bundle, bytes);
    } catch (err) {
      const wait = Number(err?.parameters?.retry_after);
      if (err?.type === 'RATE_LIMITED' && attempt < 3 && Number.isFinite(wait)) {
        await new Promise((r) => setTimeout(r, Math.min(wait, 60) * 1000));
        continue;
      }
      // Attach the blob hash when the error has none, so the message can name the file.
      if (err && typeof err === 'object' && !err.parameters?.hash) {
        err.parameters = { ...(err.parameters || {}), hash };
      }
      throw err;
    }
  }
}

// Translate a static error's blob hash into a file path and add a remedy.
function describeStaticError(err, plan) {
  const base = describeServerError(err);
  const hash = err?.parameters?.hash;
  const rel = hash && plan?.scan
    ? Object.entries(plan.scan.manifest).find(([, e]) => e.hash === hash)?.[0]
    : undefined;
  const file = rel ? `${plan.source}/${rel}` : null;
  switch (err?.type) {
    case 'FORBIDDEN_TYPE':
      return `${file ?? base}: executable content is not allowed in static files. Remove it from the build output and push again.`;
    case 'SIZE_MISMATCH':
    case 'HASH_MISMATCH':
    case 'LENGTH_MISMATCH':
      return `${file ? file + ': ' : ''}${base}. The build output changed while pushing — run push again.`;
    case 'STATIC_NOT_PREPARED':
      return `${base}. The upload window expired — run push again.`;
    case 'RATE_LIMITED':
      return `${base}. Try again in ${err.parameters?.retry_after ?? 'a few'} seconds.`;
    default:
      // No error envelope: the request was refused before reaching the application.
      if (err?.status === 413 && !err?.type) {
        const size = rel ? formatBytes(plan.scan.manifest[rel].size) : null;
        return `${file ?? 'upload'}${size ? ` (${size})` : ''}: the server refused the upload as too large (HTTP 413).`;
      }
      return file && !base.includes(rel) ? `${file}: ${base}` : base;
  }
}

/**
 * Resolve raw `push` targets against the scanned module paths. A target is a
 * file (with or without `.js` or the on-disk prefix) or a directory. No fs access.
 * @returns {{ targets: Set<string>, bad: string[] }}
 */
export function resolveTargetSet(rawTargets, scanned) {
  const scannedSet = new Set(scanned);
  const targets = new Set();
  const bad = [];
  for (const raw of rawTargets) {
    const norm = toModulePath(raw);
    if (scannedSet.has(norm)) {
      targets.add(norm);
      continue;
    }
    // Bare module name without `.js`.
    const withExt = norm.endsWith('.js') ? norm : `${norm}.js`;
    if (scannedSet.has(withExt)) {
      targets.add(withExt);
      continue;
    }
    // A directory; the bare module root selects every module.
    const dir = norm.replace(/\/+$/, '');
    const under = dir === '' || dir === MODULE_ROOT
      ? scanned.slice()
      : scanned.filter((p) => p.startsWith(dir + '/'));
    if (under.length) {
      under.forEach((p) => targets.add(p));
      continue;
    }
    bad.push(raw);
  }
  return { targets, bad };
}

function resolveTargets(rawTargets, scanned) {
  const { targets, bad } = resolveTargetSet(rawTargets, scanned);
  if (bad.length) {
    const w = Math.max(...bad.map((t) => t.length));
    const lines = bad.map(
      (t) => `  ${t.padEnd(w)}  — ${fs.existsSync(t) || existsWd(toModulePath(t)) ? 'not in a deployed module directory' : 'not found'}`
    );
    fatal(
      `Cannot deploy:\n${lines.join('\n')}\n` +
      `Run "tgcloud status" to see deployable files.`
    );
  }
  return targets;
}

// A mismatch may also arrive as `current_revision` or HTTP 409.
function isRevisionMismatch(err) {
  if (err.type === 'REVISION_MISMATCH') return true;
  const p = err.parameters || {};
  return typeof p.current_revision === 'number' || err.status === 409;
}

function showRevisionMismatchHelp(err) {
  const p = err.parameters || {};
  console.error(chalk.yellow(
    '\nServer has new revisions since your last sync.'
  ));
  if (p.current_revision != null) {
    console.error(chalk.dim(`  Server revision: ${p.current_revision}`));
  }
  if (p.expected_revision != null) {
    console.error(chalk.dim(`  Your revision:   ${p.expected_revision}`));
  }
  console.error(
    '\nOptions:\n' +
    '  tgcloud fetch           — pull latest into snapshot, then re-check diff\n' +
    '  tgcloud pull            — pull latest into both snapshot and working dir\n' +
    '  tgcloud push --force    — overwrite server state (dangerous)'
  );
}
